olor(0, pixels.Color(0, 255 - i, i));  // \u7dd1\u304c\u6e1b\u5c11\u3057\u3001\u9752\u304c\u5897\u52a0\n    pixels.show();\n    delay(10);  // \u30b9\u30e0\u30fc\u30ba\u3055\u3092\u8abf\u6574\u3059\u308b\u305f\u3081\u306e\u9045\u5ef6\n  }\n\n  // \u9752\u304b\u3089\u8d64\u3078\u306e\u9077\u79fb\n  for (int i = 0; i <= 255; i++) {\n    pixels.setPixelColor(0, pixels.Color(i, 0, 255 - i));  // \u9752\u304c\u6e1b\u5c11\u3057\u3001\u8d64\u304c\u5897\u52a0\n    pixels.show();\n    delay(10);  // \u30b9\u30e0\u30fc\u30ba\u3055\u3092\u8abf\u6574\u3059\u308b\u305f\u3081\u306e\u9045\u5ef6\n  }\n}\n")),(0,r.yg)("ul",null,(0,r.yg)("li",{parentName:"ul"},(0,r.yg)("strong",{parentName:"li"},"\u30b9\u30c6\u30c3\u30d7 3.")," \u30dc\u30fc\u30c9\u30e2\u30c7\u30eb\u3092 ",(0,r.yg)("strong",{parentName:"li"},"XIAO RA4M1")," \u306b\u9078\u629e\u3057\u3001\u6b63\u3057\u3044\u30dd\u30fc\u30c8\u756a\u53f7\u3092\u9078\u629e\u3057\u3066\u30d7\u30ed\u30b0\u30e9\u30e0\u3092\u30a2\u30c3\u30d7\u30ed\u30fc\u30c9\u3057\u307e\u3059\u3002")),(0,r.yg)("div",{style:{textAlign:"center"}},(0,r.yg)("img",{src:"https://files.seeedstudio.com/wiki/XIAO-R4AM1/img/rgb_led.gif",style:{width:600,height:"auto"}})),(0,r.yg)("h2",{id:"\u30d0\u30c3\u30c6\u30ea\u30fc\u3068\u96fb\u6e90\u7ba1\u7406"},"\u30d0\u30c3\u30c6\u30ea\u30fc\u3068\u96fb\u6e90\u7ba1\u7406"),(0,r.yg)("p",null,"\u8ffd\u52a0\u306e\u30b3\u30f3\u30dd\u30fc\u30cd\u30f3\u30c8\u306a\u3057\u3067\u30d0\u30c3\u30c6\u30ea\u30fc\u96fb\u5727\u3092\u8aad\u307f\u53d6\u308b\u3053\u3068\u306f\u53ef\u80fd\u3067\u3059\u304b\uff1f\u306f\u3044\u3001XIAO RA4M1\u3092\u4f7f\u7528\u3059\u308c\u3070\u3053\u308c\u307e\u3067\u4ee5\u4e0a\u306b\u7c21\u5358\u3067\u3059\u3002\u4ee5\u524d\u306eXIAO\u30d5\u30a1\u30df\u30ea\u30fc\u306e\u30e1\u30f3\u30d0\u30fc\u3001\u4f8b\u3048\u3070",(0,r.yg)("a",{parentName:"p",href:"https://wiki.seeedstudio.com/ja/XIAO_ESP32C3_Getting_Started/#check-the-battery-voltage"},"XIAO ESP32C3"),"\u3067\u306f\u3001\u30d0\u30c3\u30c6\u30ea\u30fc\u96fb\u5